1	/**
2	 * What a stage is.
3	 *
4	 * The shape of one deployed copy of the hosting: its account and region,
5	 * its domain, its sign-in clients, its mail identity, its plans and the
6	 * words on its pages. The values are not in this file (see `envConfig`
7	 * below): they are one operator's, and this repository is anyone's to
8	 * read and build from.
9	 */
10	import { existsSync, readFileSync } from "node:fs";
11	import { join } from "node:path";
12	
13	/** A stage's name: a short lowercase word, `dev` and `prd` here. */
14	export type EnvName = string;
15	
16	export interface EnvConfig {
17	  name: EnvName;
18	  /** The AWS account this environment deploys into. */
19	  account: string;
20	  /**
21	   * Everything lives in us-east-1.
22	   *
23	   * Not preference: CloudFront can only use an ACM certificate issued in
24	   * us-east-1, and keeping the whole stack there avoids a cross-region
25	   * reference for the sake of one certificate. When an API arrives that wants
26	   * to live nearer someone, it can have its own region and its own stack.
27	   */
28	  region: string;
29	  /** The hostname the app is served from. */
30	  domain: string;
31	  /** The Route 53 zone that answers for it, which already exists. */
32	  zone: string;
33	  /**
34	   * Explicit zone id, when you would rather not have CDK look it up.
35	   *
36	   * A lookup needs credentials at synth time and caches the answer into
37	   * `cdk.context.json`, which is a nuisance in a repo deploying to two
38	   * accounts: the cached dev zone would be used for prd. Setting the id
39	   * removes the lookup entirely.
40	   */
41	  zoneId?: string;
42	  /** Retain buckets and logs in production; let dev be torn down cleanly. */
43	  retain: boolean;
44	  /**
45	   * The WorkOS AuthKit client the app signs people in with, so the API can
46	   * check that a token was issued for *this* app and not another one in the
47	   * same WorkOS account. Public, it appears in every sign-in URL, so it is
48	   * written here rather than kept as a secret, and it matches the one the app
49	   * is built with.
50	   */
51	  workosClientId: string;
52	  /**
53	   * The WorkOS application the command line signs in with, through the
54	   * device flow: a public client of its own, so its session policy (a month
55	   * idle rather than two days) and its redirects are not the browser's.
56	   * `runlog login` asks the API for it, so nothing is baked into the package.
57	   */
58	  workosCliClientId: string;
59	  /**
60	   * Where invitations are sent from. The verified SES identity lives in a
61	   * region of its own (core-infra put it in us-west-2), so both are named.
62	   */
63	  email: { from: string; region: string; identity: string };
64	  /**
65	   * What the hosted pages say about who runs this copy. The app itself is
66	   * generic and open source; these are the words that make an address of
67	   * it a service someone operates. They land in `hosted.json` and the legal
68	   * pages at publish time, so the app reads them rather than carrying them.
69	   */
70	  /**
71	   * Whether plans gate anything. Off, everything on the pricing page is
72	   * open to everyone and nothing is charged; on, hosting a table needs
73	   * Plus. Dev runs gated so the gates are exercised; production stays
74	   * open until Stripe is live there. Config, never a branch.
75	   */
76	  gates: boolean;
77	  /**
78	   * What is sold, by Stripe id. Prices are public, they appear in every
79	   * Checkout, so they are written here; the ids come from
80	   * `hosted/scripts/stripe-setup.ts`, run once per environment. Empty until then,
81	   * and an empty price is a plan that cannot be bought yet.
82	   */
83	  stripe: {
84	    prices: {
85	      plusMonthly: string;
86	      plusYearly: string;
87	      hostedMonthly: string;
88	      hostedYearly: string;
89	      serverMonthly: string;
90	      serverYearly: string;
91	    };
92	    /** The feature lookup keys Stripe entitles; what `entitlements` in `GET /api/me` carries. */
93	    features: { plus: string; hostedLicensing: string; server: string };
94	    /** The platform's share of a sale, in basis points, by whether the publisher subscribes to hosted licensing. */
95	    applicationFeeBps: { subscribed: number; unsubscribed: number };
96	  };
97	  /**
98	   * Monitoring of the handlers, when the operator has somewhere to send it.
99	   * New Relic's Lambda layer wraps both functions: traces, errors and the
100	   * function logs, with request bodies, the authorization header and
101	   * addresses kept out. Absent, the functions run bare, which is what a
102	   * copy without an account there wants.
103	   */
104	  /**
105	   * The Discord application the bot is, when the operator has made one.
106	   * Both values are public: the id is in every install link, and the key
107	   * is what Discord signs interactions with, shown on the application's
108	   * page for anyone to check against. The bot's token is a secret and
109	   * lives in Secrets Manager. Absent, the interactions endpoint answers
110	   * that it is not configured and nothing about Discord is offered.
111	   */
112	  discord?: {
113	    applicationId: string;
114	    publicKey: string;
115	    /**
116	     * The SKU of a guild subscription sold through Discord's own store
117	     * (Monetization in the developer portal), where one is set up: a
118	     * server whose members bought it holds the server plan the same as
119	     * one whose owner subscribed here. Absent, the store is not consulted.
120	     */
121	    serverSku?: string;
122	  };
123	  apm?: {
124	    newRelic: {
125	      /** The New Relic account the telemetry goes to; its parent's, as the trusted key, where there is one. */
126	      accountId: string;
127	      trustedAccountKey?: string;
128	      /** The layer's version for this region and runtime; NewRelicNodeJS24XARM64 as published by New Relic. */
129	      layerVersion: number;
130	    };
131	  };
132	  hosted: {
133	    /** The full legal name, on the terms, the policies, the publisher agreement and every copyright line. */
134	    operator: string;
135	    /** The short name, for a footer, an about page, and anywhere nothing is agreed to. */
136	    operatorShort: string;
137	    /** The operator's own site, where the name in a footer goes; absent, the name goes to the about page. */
138	    operatorUrl?: string;
139	    /** Where support, privacy requests and security reports go. */
140	    support: string;
141	    /**
142	     * The terms' version, and the day they took effect. Bump the version
143	     * when the terms or the privacy policy change in a way that matters:
144	     * the app asks everyone signed in to accept the new one once.
145	     */
146	    termsVersion: string;
147	    termsDate: string;
148	    /** Whether the app shows plans, checkout and the portal. Off until Stripe is set up for the environment. */
149	    billing: boolean;
150	    /**
151	     * Whether the app's bundled marketplace includes the engine-testing pack:
152	     * dev yes, production no. Absent is treated as `false`, so a stage
153	     * whose configuration predates this flag stays production-safe rather
154	     * than shipping a test bench nobody asked for.
155	     */
156	    testing: boolean;
157	  };
158	}
159	
160	/**
161	 * Where a stage's configuration comes from.
162	 *
163	 * Not from this file. A stage is one operator's identity: its domain, its
164	 * sign-in clients, its prices, the words on its pages. None of that is
165	 * secret, but none of it belongs in a repository anyone can read and
166	 * build from, so it lives as one JSON document per stage: on the GitHub
167	 * environment as the `RUNLOG_ENV_CONFIG` variable, and on a machine as
168	 * `hosted/infra/env/<stage>.json`, which git ignores. `env/example.json`
169	 * is the template and what the tests run against.
170	 */
171	const NAME = /^[a-z][a-z0-9-]{0,15}$/;
172	
173	/**
174	 * The account to deploy into.
175	 *
176	 * Deliberately *not* `CDK_DEFAULT_ACCOUNT`. The CDK CLI overwrites that with
177	 * whatever account the resolved credentials belong to, so on a machine with
178	 * an SSO session open it silently becomes the management account, and this
179	 * value ends up in the bucket's name. `RUNLOG_TARGET_ACCOUNT` is set
180	 * explicitly by the `run-cdk` action and cannot be clobbered.
181	 */
182	function accountFor(name: EnvName): string {
183	  const target = process.env.RUNLOG_TARGET_ACCOUNT;
184	  if (target) return target;
185	  return required(`RUNLOG_${name.toUpperCase().replace(/-/g, "_")}_ACCOUNT`);
186	}
187	
188	function required(name: string): string {
189	  const value = process.env[name];
190	  if (!value) {
191	    throw new Error(
192	      `${name} is not set. The account is named by environment variable so this repository is not tied to one person's AWS. See docs/self-hosting.md.`,
193	    );
194	  }
195	  return value;
196	}
197	
198	function readStage(name: EnvName): Record<string, unknown> {
199	  const inline = process.env["RUNLOG_ENV_CONFIG"];
200	  const file = join(__dirname, "..", "env", `${name}.json`);
201	  const text = inline ?? (existsSync(file) ? readFileSync(file, "utf8") : undefined);
202	  if (!text) {
203	    throw new Error(
204	      `No configuration for the stage "${name}". Set RUNLOG_ENV_CONFIG to its JSON, ` +
205	        `or write ${file} (env/example.json is the template). See docs/self-hosting.md.`,
206	    );
207	  }
208	  const parsed: unknown = JSON.parse(text);
209	  if (!parsed || typeof parsed !== "object" || Array.isArray(parsed))
210	    throw new Error(`The configuration for "${name}" is not a JSON object`);
211	  return parsed as Record<string, unknown>;
212	}
213	
214	const isRecord = (v: unknown): v is Record<string, unknown> => Boolean(v) && typeof v === "object" && !Array.isArray(v);
215	const str = (v: unknown, at: string): string => {
216	  if (typeof v !== "string" || !v) throw new Error(`configuration: ${at} must be a non-empty string`);
217	  return v;
218	};
219	const bool = (v: unknown, at: string): boolean => {
220	  if (typeof v !== "boolean") throw new Error(`configuration: ${at} must be true or false`);
221	  return v;
222	};
223	const num = (v: unknown, at: string): number => {
224	  if (typeof v !== "number" || !Number.isFinite(v)) throw new Error(`configuration: ${at} must be a number`);
225	  return v;
226	};
227	const rec = (v: unknown, at: string): Record<string, unknown> => {
228	  if (!isRecord(v)) throw new Error(`configuration: ${at} must be an object`);
229	  return v;
230	};
231	/** Like `bool`, but a missing key takes the given default rather than erroring. */
232	const boolOr = (v: unknown, at: string, fallback: boolean): boolean => (v === undefined ? fallback : bool(v, at));
233	
234	/** The zone id, when the operator would rather CDK did not look it up. */
235	function zoneIdFor(name: EnvName): string | undefined {
236	  return process.env["RUNLOG_ZONE_ID"] || process.env[`RUNLOG_${name.toUpperCase().replace(/-/g, "_")}_ZONE_ID`] || undefined;
237	}
238	
239	export function envConfig(name: EnvName): EnvConfig {
240	  const c = readStage(name);
241	  const email = rec(c["email"], "email");
242	  const stripe = rec(c["stripe"], "stripe");
243	  const prices = rec(stripe["prices"], "stripe.prices");
244	  const features = rec(
245	    { plus: "plus", hostedLicensing: "hosted-licensing", server: "server", ...(isRecord(stripe["features"]) ? stripe["features"] : {}) },
246	    "stripe.features",
247	  );
248	  const fee = rec(stripe["applicationFeeBps"] ?? { subscribed: 0, unsubscribed: 500 }, "stripe.applicationFeeBps");
249	  const hosted = rec(c["hosted"], "hosted");
250	  const price = (key: string): string => {
251	    const v = prices[key] ?? "";
252	    if (typeof v !== "string") throw new Error(`configuration: stripe.prices.${key} must be a string`);
253	    return v;
254	  };
255	  const zoneId = zoneIdFor(name) ?? (typeof c["zoneId"] === "string" && c["zoneId"] ? c["zoneId"] : undefined);
256	  return {
257	    name,
258	    // Fixed, not inherited. The CDK CLI overwrites CDK_DEFAULT_REGION with
259	    // whatever region the resolved credentials point at, so reading it
260	    // would mean the stack quietly followed a developer's default profile;
261	    // and CloudFront will not accept a certificate from anywhere but
262	    // us-east-1.
263	    region: "us-east-1",
264	    account: accountFor(name),
265	    domain: str(c["domain"], "domain"),
266	    zone: str(c["zone"], "zone"),
267	    ...(zoneId ? { zoneId } : {}),
268	    retain: bool(c["retain"], "retain"),
269	    workosClientId: str(c["workosClientId"], "workosClientId"),
270	    workosCliClientId: str(c["workosCliClientId"], "workosCliClientId"),
271	    email: {
272	      from: str(email["from"], "email.from"),
273	      region: str(email["region"], "email.region"),
274	      identity: str(email["identity"], "email.identity"),
275	    },
276	    gates: bool(c["gates"], "gates"),
277	    stripe: {
278	      prices: {
279	        plusMonthly: price("plusMonthly"),
280	        plusYearly: price("plusYearly"),
281	        hostedMonthly: price("hostedMonthly"),
282	        hostedYearly: price("hostedYearly"),
283	        serverMonthly: price("serverMonthly"),
284	        serverYearly: price("serverYearly"),
285	      },
286	      features: {
287	        plus: str(features["plus"], "stripe.features.plus"),
288	        hostedLicensing: str(features["hostedLicensing"], "stripe.features.hostedLicensing"),
289	        server: str(features["server"], "stripe.features.server"),
290	      },
291	      applicationFeeBps: {
292	        subscribed: num(fee["subscribed"], "stripe.applicationFeeBps.subscribed"),
293	        unsubscribed: num(fee["unsubscribed"], "stripe.applicationFeeBps.unsubscribed"),
294	      },
295	    },
296	    ...(isRecord(c["discord"])
297	      ? {
298	          discord: {
299	            applicationId: str(c["discord"]["applicationId"], "discord.applicationId"),
300	            publicKey: str(c["discord"]["publicKey"], "discord.publicKey"),
301	            ...(typeof c["discord"]["serverSku"] === "string" && c["discord"]["serverSku"].trim()
302	              ? { serverSku: c["discord"]["serverSku"].trim() }
303	              : {}),
304	          },
305	        }
306	      : {}),
307	    ...(isRecord(c["apm"]) && isRecord(c["apm"]["newRelic"])
308	      ? {
309	          apm: {
310	            newRelic: {
311	              accountId: str(c["apm"]["newRelic"]["accountId"], "apm.newRelic.accountId"),
312	              ...(typeof c["apm"]["newRelic"]["trustedAccountKey"] === "string"
313	                ? { trustedAccountKey: c["apm"]["newRelic"]["trustedAccountKey"] }
314	                : {}),
315	              layerVersion: num(c["apm"]["newRelic"]["layerVersion"] ?? 52, "apm.newRelic.layerVersion"),
316	            },
317	          },
318	        }
319	      : {}),
320	    hosted: {
321	      operator: str(hosted["operator"], "hosted.operator"),
322	      operatorShort: str(hosted["operatorShort"], "hosted.operatorShort"),
323	      ...(typeof hosted["operatorUrl"] === "string" && hosted["operatorUrl"] ? { operatorUrl: hosted["operatorUrl"] } : {}),
324	      support: str(hosted["support"], "hosted.support"),
325	      termsVersion: str(hosted["termsVersion"], "hosted.termsVersion"),
326	      termsDate: str(hosted["termsDate"], "hosted.termsDate"),
327	      billing: bool(hosted["billing"], "hosted.billing"),
328	      testing: boolOr(hosted["testing"], "hosted.testing", false),
329	    },
330	  };
331	}
332	
333	/**
334	 * Which environment this run is for.
335	 *
336	 * `AWS_ENVIRONMENT` is the name the shared workflow actions already use across
337	 * these repositories; `RUNLOG_ENV` is accepted too so a local `cdk diff` reads
338	 * the way the rest of this project does.
339	 */
340	export function currentEnv(): EnvName {
341	  const raw = process.env.AWS_ENVIRONMENT ?? process.env.RUNLOG_ENV ?? "dev";
342	  if (!NAME.test(raw)) {
343	    throw new Error(`AWS_ENVIRONMENT must be a short lowercase name such as "dev" or "prd", not ${JSON.stringify(raw)}`);
344	  }
345	  return raw;
346	}
